// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by measure.creative.score@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before measure.creative.score started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "measure.creative.score",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "measure.creative.score", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// Score = weighted performance against the vertical's own benchmark, damped by confidence.
// Comparing a plumber's CTR to a SaaS CTR on an absolute scale is meaningless; comparing
// each to its own vertical benchmark is not.
const profile = $json;
const rows = $('Envelope In').first().json.payload.metrics || [];
const bench = Object.fromEntries((profile.kpis || []).map(k => [k.metric, k.benchmark]));
const primary = (profile.kpis || []).filter(k => k.primary).map(k => k.metric);

const MIN_IMPRESSIONS = 300;
const out = rows.map(r => {
  const parts = [];
  const add = (metric, value) => { const b = bench[metric]; if (value != null && b) parts.push(Math.min(2, value / b) / 2); };
  add('engagement_rate', r.engagement_rate);
  add('click_through_rate', r.ctr);
  add('conversion_rate', r.cvr);
  add('watch_through_rate', r.watch_through_rate);
  const raw = parts.length ? parts.reduce((a, b) => a + b, 0) / parts.length : null;
  const confidence = Math.min(1, (r.impressions ?? 0) / MIN_IMPRESSIONS);
  // Shrink toward 0.5 when the sample is thin: an unproven winner is not a winner.
  const score = raw == null ? null : (raw * confidence) + (0.5 * (1 - confidence));
  return { ...r, raw_score: raw, confidence, score, decisive: confidence >= 1 && raw != null, primary_kpis: primary };
});

const ranked = out.filter(x => x.score != null).sort((a, b) => b.score - a.score);
return [{ json: {
  scored: out,
  winner: ranked.find(x => x.decisive) || null,
  top_decile_threshold: ranked.length >= 10 ? ranked[Math.floor(ranked.length * 0.1)].score : null,
  note: ranked.some(x => x.decisive) ? null : 'No result has enough impressions to be decisive yet; do not reallocate on this data.'
} }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "measure.creative.score",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 0,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "measure.creative.score", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

